1: angular.module('deciframeApp').controller('SequenciaController', function($http, $window, ngProgressFactory, $anchorScroll, $location, GENEROS) {
2:   var COR_ACORDE = '#2E1C74';
3: 
4:   var mapearSequencia = function(sequencia) {
5:     return {
6:       'id': sequencia.id,
7:       'nome': sequencia.nome,
8:       'acordes': sequencia.acordes.map(function(acorde) {
9:         return { 'acorde': acorde, 'cor': COR_ACORDE };
10:       })
11:     };
12:   };
13: 
14:   var vm = this;
15:   vm.sequencias = [];
16:   vm.novaSequencia = { 'nome': '', 'acordes': '' };
17:   vm.erroCadastro = '';
18:   vm.erroCatalogo = '';
19:   vm.carregandoSequencias = false;
20:   vm.cadastrando = false;
21:   vm.minhaSequencia = {};
22:   vm.isSearching = false;
23:   vm.showSearchResultsCount = false;
24:   vm.esfigeSpeech =  "";
25:   vm.musics = [];
26:   vm.generos = GENEROS;
27:   vm.meuGenero = "";
28:   vm.progressbar = ngProgressFactory.createInstance();
29: 
30:   vm.carregarSequencias = function() {
31:     vm.carregandoSequencias = true;
32:     vm.erroCatalogo = '';
33:     return $http.get('sequencias')
34:       .success(function(data) {
35:         vm.carregandoSequencias = false;
36:         vm.sequencias = data.map(mapearSequencia);
37:       })
38:       .error(function() {
39:         vm.carregandoSequencias = false;
40:         vm.erroCatalogo = "Não foi possível carregar o catálogo de sequências.";
41:       });
42:   };
43: 
44:   vm.carregarSequencias();
45: 
46:   vm.temAcorde = function(acorde) {
47:     if (vm.minhaSequencia.acordes) {
48:       return (vm.minhaSequencia.acordes.indexOf(acorde) > -1);
49:     } else {
50:       return false;
51:     }
52:   }
53: 
54:   vm.pesquisarPorSequencia = function(sequencia) {
55:     if (sequencia) {
56:       vm.minhaSequencia = sequencia;
57:     }
58:     if (!vm.minhaSequencia.id) {
59:       return;
60:     }
61:     vm.progressbar.start();
62:     vm.esfigeSpeech = "Procurando músicas com base na sequencia...";
63:     vm.isSearching = true;
64:     vm.showSearchResultsCount = false;
65:     vm.musics = [];
66: 
67:     var apiUrl = "";
68:     var searchString = "similares?sequencia_id=".concat(vm.minhaSequencia.id);
69:     if (vm.meuGenero !== "" && vm.meuGenero !== null) {
70:       searchString += "&generos="+vm.meuGenero;
71:     }
72:     $http.get(apiUrl.concat(searchString))
73:       .success(function(data) {
74:         vm.progressbar.complete();
75:         vm.esfigeSpeech = "Encontrei essas músicas";
76:         vm.isSearching = false;
77:         vm.showSearchResultsCount = true;
78:         vm.musics = data;
79:       })
80:       .error(function(data) {
81:         vm.progressbar.complete();
82:         vm.esfigeSpeech = "Ops! Algo errado.";
83:         vm.isSearching = false;
84:         vm.showSearchResultsCount = false;
85:       });
86:   }
87: 
88:   vm.cadastrarSequencia = function() {
89:     vm.erroCadastro = '';
90:     vm.cadastrando = true;
91: 
92:     var acordes = [];
93:     if (vm.novaSequencia.acordes) {
94:       acordes = vm.novaSequencia.acordes.split(',').map(function(acorde) {
95:         return acorde.trim();
96:       }).filter(function(acorde) {
97:         return acorde.length > 0;
98:       });
99:     }
100: 
101:     $http.post('sequencias', {
102:       'nome': vm.novaSequencia.nome,
103:       'acordes': acordes
104:     }).success(function() {
105:       vm.cadastrando = false;
106:       vm.novaSequencia = { 'nome': '', 'acordes': '' };
107:       vm.carregarSequencias();
108:     }).error(function(data, status) {
109:       vm.cadastrando = false;
110:       if (data && data.erro) {
111:         vm.erroCadastro = data.erro;
112:       } else if (status === 413) {
113:         vm.erroCadastro = "O cadastro é grande demais.";
114:       } else if (status === 400) {
115:         vm.erroCadastro = "Dados inválidos.";
116:       } else {
117:         vm.erroCadastro = "Não foi possível cadastrar a sequência.";
118:       }
119:     });
120:   }
121: 
122:   vm.limparPesquisa = function() {
123:     vm.minhaSequencia = {};
124:     vm.musics = [];
125:   }
126: 
127:   vm.goToLirics = function(music) {
128:     $window.open(music.url);
129:   };
130: 
131:   vm.goToResults = function() {
132:     vm.showSearchResultsCount = false;
133:     $("body").animate({scrollTop: $("#results").offset().top}, "slow");
134:   };
135: });

angular.module('deciframeApp').config(function($routeProvider) {
  $routeProvider
    .when('/', {
      templateUrl: "templates/home.html",
      controller: "HomeController"
    })
    .when('/poracordes', {
      templateUrl: "templates/acordes.html",
      controller: "AcordesController",
      controllerAs: "Chords"
    })
    .when('/pormusica', {
      templateUrl: "templates/musica.html",
      controller: "MusicaController",
      controllerAs: "Musica"
    })
    .when('/porsequencia', {
      templateUrl: "templates/sequencia.html",
      controller: "SequenciaController",
      controllerAs: "Sequencia"
    })
    .when('/sobre', {
      templateUrl: "templates/about.html",
      controller: "AboutController"
    })
    .otherwise({
      redirectTo: '/'
    });
});
